    printStoreData(storeId) {
        const store = this.state.storeListData.find(store => store.id === storeId);
        return store.name + ' (🆔 :' + store.id + ') ' + this.printLocationData(store.locationId);
    }

    printLocationData(locationId) {
        const location = locationId === null ? null : this.state.locationListData.find(location => location.id === locationId);
        const locationStr = location === null ? 'N/A' : (location.name + '(' + location.id + ")" + ", " + location.description + ", " + location.city);
        return "📍 LOCATION : " + locationStr;
    }

    toggleFilter() {
        //this function will toggle the filter(s)
        let filteredExpenses = this.state.expensesListData;
        const filterItems = this.state.filterItems;

        filterItems.dateOfPurchaseFilter = document.getElementById('dateOfPurchaseFilter').value;            
        this.setState({
            filterItems
        });

        if((this.state.filterItems.dateOfPurchaseFilter === null || this.state.filterItems.dateOfPurchaseFilter.length <= 0)
            && this.state.filterItems.paymentInstrumentFilter === null 
            && this.state.filterItems.productFilter === null) {
            alert("ℹ️ No filtering-value added.");
            return;
        }

        //engage `dateOfPurchaseFilter`
        if(this.state.filterItems.dateOfPurchaseFilter !== null) {
            filteredExpenses = filteredExpenses.filter(expense => expense.dateAndTimeOfPurchase.includes(this.state.filterItems.dateOfPurchaseFilter));
        }

        //engage `paymentInstrumentFilter`
        if(this.state.filterItems.paymentInstrumentFilter !== null) {
            filteredExpenses = filteredExpenses.filter(expense => expense.payment.paymentInstrument.includes(this.state.filterItems.paymentInstrumentFilter));            
        }

        //engage `productFilter`
        if(this.state.filterItems.productFilter !== null) {
            const filteredProductId = this.state.filterItems.productFilter.product.id;
            filteredExpenses = filteredExpenses.filter(expense => {
                const itemsArray = expense.items;
                return itemsArray.filter(item => item.productId === filteredProductId).length > 0;
            });            
        }

        this.setState({
            filteredExpensesListData: filteredExpenses,
            filtersEngaged : !this.state.filtersEngaged
        });
    }

    testRenderingLogicV2() {
        const categoryPaymentHistory = {
            category: {	
                id : 93,
                name: 'paneer - cottage cheese',
                unit_of_measurement: 'GRAM' // GRAM, COUNT, ML
            },
            products : [
                { 
                    id : 485,
                    name: 'Mother Dairy Paneer',
                    brand : {id : 23, name : 'Mother Dairy'},
                },
                { 
                    id : 345, 
                    name: 'Amul malai paneer', 
                    brand : {id : 465, name : 'miklymist'} 
                }
            ],
            priceMatrix : [
                { productId : 485, quantity : 400, amount: 100, expenseDate : '2023-11-10 15:04'},
                { productId : 485, quantity : 500, amount: 500, expenseDate : '2023-11-12 15:04'},
                { productId : 345, quantity : 450, amount: 500, expenseDate : '2023-11-15 15:04'},
                { productId : 345, quantity : 450, amount: 400, expenseDate : '2023-11-20 15:04'},
                { productId : 345, quantity : 450, amount: 700, expenseDate : '2023-12-15 15:04'},
                { productId : 485, quantity : 500, amount: 400, expenseDate : '2023-12-23 15:04'},
                { productId : 345, quantity : 450, amount: 100, expenseDate : '2023-12-25 15:04'},
            ]
        };

        const plotlyFinalData = [];
        const COLORS = [
            "red","green","blue","#b59a14","#b514a5","black","orange"
        ];
        
        categoryPaymentHistory
            .products
            .forEach((product, index) => {
                let x = [] , y = [];

                categoryPaymentHistory
                    .priceMatrix
                    .forEach(paymentHistory => {
                        if(paymentHistory.productId === product.id) {
                            x.push(paymentHistory.expenseDate);
                            y.push(findCostPer(paymentHistory.quantity, paymentHistory.amount, 100)); //cost per 100gm
                        }
                    });

                plotlyFinalData.push(
                    {
                        x: [ ...x ],
                        y: [ ...y ],
                        type: 'scatter',
                        mode: 'lines+markers',
                        marker: {color: COLORS[index]},
                        name: `price`
                    }
                );
            });

        return plotlyFinalData;
    }

    testRenderingLogicV3() {
        if(localStorage.plotlyCategoryId === undefined)
            return null;
            
        const categoryId = localStorage.plotlyCategoryId;

        let category = this.state.categoryListData.find((category) => category.id == categoryId);
        //console.log("testRenderingLogicV3() : category = ", category);

        let products = this.state.productListData.filter(product => product.categoryId === category.id);
        // console.log("testRenderingLogicV3() : products = ", products);

        const plotlyFinalData = [];
        const COLORS = [
            "red","green","blue","#b59a14","#b514a5","black","orange"
        ];

        products.forEach((product, index) => {
            let x = [] , y = [];
            this.state.expensesListData.forEach(expense => {
                expense.items.forEach(item => {
                    if(item.productId === product.id) {
                        x.push(expense.dateAndTimeOfPurchase);
                        y.push(findCostPer(item.quantity, item.amount, 1000)); //cost per 1000gm
                    }

                });
            });

            plotlyFinalData.push(
                {
                    x: [ ...x ],
                    y: [ ...y ],
                    type: 'scatter',
                    mode: 'lines+markers',
                    marker: {color: COLORS[index]},
                    name: product.name
                }
            );
        });

        // this.setState({
        //     plotlyData : {
        //         category,
        //         products
        //     }
        // });

        return plotlyFinalData;
    }

    //default
